  onCreated: (idea: IdeaDTO) => void;
  onCancel: () => void;
}) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [scores, setScores] = useState<Scores>({
    differentiation: 3,
    evidence: 3,
    cost: 3,
    reversibility: 3,
  });
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setLoading(true);

    const res = await fetch("/api/ideas", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, ...scores }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      setError(data.error ?? "Could not save idea");
      setLoading(false);
      return;
    }

    const data = await res.json();
    onCreated(data.idea);
  }

  return (
    <form onSubmit={onSubmit} className="space-y-5 p-5">
      <div>
        <Label htmlFor="title">Idea</Label>
        <Input
          id="title"
          required
          autoFocus
          placeholder="What's the idea?"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
      </div>
      <div>
        <Label htmlFor="description">Description (optional)</Label>
        <Textarea
          id="description"
          rows={3}
          placeholder="What is it, who is it for, why now?"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        {DIMENSION_FIELDS.map((f) => (
          <ScorePicker
            key={f.key}
