            <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
              {DIMENSIONS.map((d) => {
                const predicted = idea[d.key] as number;
                const hindsight = idea[d.hKey] as number | null;
                return (
                  <div key={d.key}>
                    <div className="text-[11px] text-muted">{d.label}</div>
