            <Button size="sm" onClick={() => setShowOutcomeForm(true)}>
              Record outcome
            </Button>
          </div>
        )}
      </Card>

      <Card className="mt-4 p-6">
        <h2 className="font-medium">Share</h2>
        <div className="mt-4">
          <ShareControl
